   "subject": "Question",
   "body": "Run 2026-11-06-ARK-316-1: the codex review of the 14 test cases (findings/spec-cases-review.md) needs 3 human decisions. \n1) Title limit. AC3 allows a 72-char summary and prefixes it with '<ticket id>: ' (81 chars), but AC6 TITLE01 caps the whole title at 72 and AC7 refuses on any lint fail. Option A (recommended): the whole MR title is 72 or less; a summary or short ticket title is used only if '<id>: <summary>' fits 72; a longer one needs --summary; I amend AC3 and AC9 wording via ark criteria amend. Option B: TITLE01 limits the summary only; the full title may be longer; I amend AC6.\n2) Nine lint ids have no meaning in the ticket. Approve the reviewer's one-line meanings? REF01 fail: ledger tracker ref missing from or contradicted by the body. REF02 fail: dependency/merge-order refs missing or contradicted. DIFF01 warn: stated change not supported by the 3-dot diff. EVID01 warn: evidence does not fit the ticket kind. EVID03 warn: evidence claim has no run artifact for the case and head. VAL02 warn: a verify item has no backticked command or no Expect clause. RISK01 warn: risk/revert text missing or too vague. SEC01 warn: security-relevant diff with no security note. ELI01 warn: problem text is jargon or implementation-only. \n3) Provenance precedence: if the human answered both gates, strategy variant ('who shaped the solution') wins. A strategy gate answered by auto does not count. Agree?\nAfter your answer I amend ACs if needed, send the cases back to the validator with the other P1/P2 fixes (unreachable risk thresholds, sensitive tier, fixture gaps), and re-review. Recommendation: A, approve meanings, agree.",
